// pnpm site:sync <site>|--all [--check]
// Regenerates every GENERATED file of a site from site.config.ts, brand/tokens.ts and the presets.
// --check writes nothing and fails when a generated file is out of date.

import { existsSync, mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join, relative } from 'node:path';
import { parseArgs } from 'node:util';
import { checkContrast, checkFonts, tokensToCss } from '@aw/brand';
import { adminIndexHtml, buildCmsConfig, cmsConfigYaml, validateCmsConfig } from '@aw/cms';
import { resolvePreset, type ResolvedPreset } from '@aw/presets';
import type { SiteConfig } from '@aw/core';
import { loadSite, ROOT, sitesFromArgs, type LoadedSite } from './lib/sites.ts';

const GEN = 'GENERATED by pnpm site:sync. Do not edit.';

export interface GeneratedFile {
  path: string;
  content: string | Buffer;
}

function fnWrapper(f: ResolvedPreset['functions'][number]): string {
  const methods = f.method.split(',');
  const rl = f.rateLimit ? `, rateLimit: { windowLimit: ${f.rateLimit.windowLimit}, windowSize: ${f.rateLimit.windowSize}, aggregateBy: ['ip', 'domain'] }` : '';
  return `// ${GEN}
import { ${f.handler.factory} } from '${f.handler.module}';
import site from '../../site.config.ts';
import data from '../../.aw/server-data.json' with { type: 'json' };

export default ${f.handler.factory}(site, data);
export const config = { path: '${f.path}', method: ${JSON.stringify(methods)}${rl} };
`;
}

function envExample(site: SiteConfig, r: ResolvedPreset): string {
  if (!r.envKeys.length) return `# ${GEN}\n# This ${r.tier} site needs no environment variables.\n`;
  const groups: Array<[string, string]> = [['mode', 'mode'], ['required', 'required for test/live'], ['optional', 'optional']];
  const lines = [`# ${GEN}`, `# Copy to .env for local testing. Set real values in Netlify (Site configuration → Environment variables).`];
  for (const [g, title] of groups) {
    const keys = r.envKeys.filter((k) => k.group === g);
    if (!keys.length) continue;
    lines.push(`# ── ${title} ${'─'.repeat(Math.max(4, 44 - title.length))}`);
    for (const k of keys) lines.push(`${k.key}=${k.example ?? ''}`.padEnd(40) + `# ${k.comment}`);
  }
  return `${lines.join('\n')}\n`;
}

function ignorePaths(name: string, r: ResolvedPreset): string[] {
  const pkgs = new Set(['core', 'i18n', 'brand', 'ui', 'seo', 'cms', 'content', 'presets', 'astro', 'whatsapp', 'payments', 'commerce', 'booking']);
  if (r.tier === 'full') pkgs.add('ops');
  return [`sites/${name}`, ...[...pkgs].sort().map((p) => `packages/${p}`), 'pnpm-lock.yaml', 'pnpm-workspace.yaml', 'package.json', '.nvmrc', 'studio.config.ts'];
}

function netlifyToml(name: string, site: SiteConfig, r: ResolvedPreset): string {
  const pkg = `@aw/site-${name}`;
  const ignore = `[ "$CACHED_COMMIT_REF" = "$COMMIT_REF" ] && exit 1; git diff --quiet $CACHED_COMMIT_REF $COMMIT_REF -- ${ignorePaths(name, r).join(' ')}`;
  const robots = site.seo.indexing ? '' : '\n    X-Robots-Tag = "noindex"';
  const fns = r.functions.length
    ? `
[functions]
  directory = "sites/${name}/netlify/functions"
  node_bundler = "esbuild"
  included_files = ["sites/${name}/.aw/server-data.json"]
`
    : '';
  return `# ${GEN}
# Netlify site settings: base directory unset, package directory = sites/${name}.

[build]
  command = "pnpm --filter ${pkg} build"
  publish = "sites/${name}/dist"
  ignore = ${JSON.stringify(ignore)}

[build.environment]
  NODE_VERSION = "24"

[context.production.environment]
  AW_STRICT_CONTENT = "1"

[context.deploy-preview.environment]
  PAYMENTS_MODE = "mock"

[context.branch-deploy.environment]
  PAYMENTS_MODE = "mock"
${fns}
[[headers]]
  for = "/*"
  [headers.values]
    Content-Security-Policy = "frame-ancestors 'self'; object-src 'none'; base-uri 'self'"
    X-Content-Type-Options = "nosniff"
    Referrer-Policy = "strict-origin-when-cross-origin"
    Permissions-Policy = "camera=(), microphone=(), geolocation=(), payment=(self)"${robots}

[[headers]]
  for = "/admin/*"
  [headers.values]
    Content-Security-Policy = "script-src 'self' 'unsafe-inline' https://unpkg.com; style-src 'self' 'unsafe-inline'; font-src 'self' https://cdn.jsdelivr.net; img-src 'self' blob: data: https://*.githubusercontent.com; connect-src 'self' blob: data: https://unpkg.com https://api.github.com https://www.githubstatus.com https://api.netlify.com https://*.githubusercontent.com; worker-src blob:; frame-src blob:; media-src blob:; manifest-src blob:"
    X-Robots-Tag = "noindex"
    Cache-Control = "no-store"

[[headers]]
  for = "/owner/*"
  [headers.values]
    X-Robots-Tag = "noindex"
    Cache-Control = "no-store"

[[headers]]
  for = "/_astro/*"
  [headers.values]
    Cache-Control = "public, max-age=31536000, immutable"
`;
}

export async function generate(s: LoadedSite): Promise<{ files: GeneratedFile[]; remove: string[]; problems: string[] }> {
  const { site, tokens, name, dir } = s;
  const r = resolvePreset(site);
  const problems: string[] = [];
  for (const i of checkContrast(tokens)) problems.push(`contrast: ${i.pair} is ${i.ratio}, needs ${i.needs}`);
  for (const i of checkFonts(tokens, site.locale)) if (i.level === 'error') problems.push(`fonts: ${i.message}`);

  const files: GeneratedFile[] = [];
  files.push({ path: 'src/styles/tokens.css', content: tokensToCss(tokens) });

  const general = existsSync(join(dir, 'src/content/settings/general.json')) ? JSON.parse(readFileSync(join(dir, 'src/content/settings/general.json'), 'utf8')) : {};
  const sizes = existsSync(join(dir, 'src/content/settings/sizes.json')) ? JSON.parse(readFileSync(join(dir, 'src/content/settings/sizes.json'), 'utf8')) : {};
  const brandName: string = general.name?.ar ?? site.slug;
  const cms = buildCmsConfig(site, r, {
    repo: process.env.AW_CMS_REPO ?? 'your-github-user/arabic-websites',
    root: relative(ROOT, dir).replace(/\\/g, '/'),
    brandName,
    skipCi: true,
    sizeOptions: (sizes.sizes ?? []).map((x: { id: string; label: { ar: string } }) => ({ value: x.id, label: x.label?.ar ?? x.id })),
  });
  for (const e of validateCmsConfig(cms)) problems.push(`cms: ${e}`);
  files.push({ path: 'public/admin/config.yml', content: cmsConfigYaml(cms) });
  files.push({ path: 'public/admin/index.html', content: adminIndexHtml({ brandName, ownerDashboard: r.modules.has('ownerDashboard') }) });
  files.push({ path: 'netlify.toml', content: netlifyToml(name, site, r) });
  files.push({ path: '.env.example', content: envExample(site, r) });

  for (const icon of ['favicon.svg', 'apple-touch-icon.png', 'og.png']) {
    const src = join(dir, 'brand', icon);
    if (existsSync(src)) files.push({ path: `public/${icon}`, content: readFileSync(src) });
  }

  const wanted = new Set<string>();
  for (const f of r.functions) {
    const path = `netlify/functions/${f.name}.mts`;
    wanted.add(path);
    files.push({ path, content: fnWrapper(f) });
  }
  const fnDir = join(dir, 'netlify/functions');
  const remove = existsSync(fnDir) ? readdirSync(fnDir).map((f) => `netlify/functions/${f}`).filter((p) => !wanted.has(p)) : [];
  return { files, remove, problems };
}

async function main() {
  const { values, positionals } = parseArgs({ allowPositionals: true, options: { check: { type: 'boolean', default: false }, all: { type: 'boolean', default: false } } });
  const names = sitesFromArgs(values.all ? ['--all'] : positionals);
  let failed = false;
  for (const name of names) {
    const s = await loadSite(name);
    const { files, remove, problems } = await generate(s);
    if (problems.length) {
      failed = true;
      console.error(`✗ ${name}\n  ${problems.join('\n  ')}`);
      continue;
    }
    const drift: string[] = [];
    for (const f of files) {
      const abs = join(s.dir, f.path);
      const current = existsSync(abs) ? readFileSync(abs) : null;
      const next = typeof f.content === 'string' ? Buffer.from(f.content) : f.content;
      if (current && current.equals(next)) continue;
      drift.push(f.path);
      if (!values.check) {
        mkdirSync(dirname(abs), { recursive: true });
        writeFileSync(abs, next);
      }
    }
    for (const r of remove) {
      drift.push(`${r} (stale)`);
      if (!values.check) rmSync(join(s.dir, r));
    }
    if (values.check && drift.length) {
      failed = true;
      console.error(`✗ ${name}: out of date: ${drift.join(', ')}. Run pnpm site:sync ${name}`);
    } else {
      console.log(`✓ ${name}${drift.length ? ` (${values.check ? 'drift' : 'wrote'}: ${drift.join(', ')})` : ' up to date'}`);
    }
  }
  if (failed) process.exit(1);
}

if (import.meta.url === `file:///${process.argv[1]?.replace(/\\/g, '/')}` || process.argv[1]?.endsWith('site-sync.ts')) {
  main().catch((e) => {
    console.error(e instanceof Error ? e.message : e);
    process.exit(1);
  });
}

